class CSaferStr : public std::basic_string<const char*>
{
public:
	CSaferStr& operator=(const char* str)
	{
		if (str == NULL)
		{
			replace(0, -1, 0);
		}
		else
		{
			size_t len = strlen(str);
			assign(len, str);
		}

		return *this;
	}
};

